"""Markdown report generation.

Each ``write_doc_XX`` function renders one file in ``docs/`` from live
pipeline objects, so the documentation is regenerated -- never hand-edited --
every time ``main.py`` runs.  Narrative sections are written here alongside
the tables they explain.
"""

from __future__ import annotations

import datetime as _dt
import textwrap
from pathlib import Path
from typing import Any, Dict, Iterable, Mapping, Sequence

import numpy as np
import pandas as pd

from . import data_loader as dl

GENERATED_BY = (
    "_This file is generated by `main.py`; edit `src/report.py` rather than "
    "the Markdown._"
)


# ---------------------------------------------------------------------------
# Markdown helpers
# ---------------------------------------------------------------------------
def md_table(frame: pd.DataFrame, floatfmt: str = "{:.4f}",
             index: bool = False, max_rows: int | None = None) -> str:
    """Render a DataFrame as a GitHub-flavoured Markdown table."""
    data = frame if max_rows is None else frame.head(max_rows)
    if index:
        data = data.reset_index()

    def fmt(value: Any) -> str:
        if isinstance(value, (float, np.floating)):
            if np.isnan(value):
                return "--"
            if np.isinf(value):
                # Distinguish "never happens" from "not available": an
                # infinite crossover means the rival never overtakes.
                return "never" if value > 0 else "-inf"
            return floatfmt.format(value)
        if isinstance(value, (bool, np.bool_)):
            return "yes" if value else "no"
        if isinstance(value, (int, np.integer)):
            return str(int(value))
        return str(value)

    header = "| " + " | ".join(str(c) for c in data.columns) + " |"
    rule = "| " + " | ".join("---" for _ in data.columns) + " |"
    rows = ["| " + " | ".join(fmt(v) for v in row) + " |"
            for row in data.itertuples(index=False, name=None)]
    note = ""
    if max_rows is not None and len(frame) > max_rows:
        note = f"\n\n_({len(frame) - max_rows} further rows omitted.)_"
    return "\n".join([header, rule, *rows]) + note


def _write(path: str | Path, sections: Sequence[str]) -> Path:
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    body = "\n\n".join(s.strip("\n") for s in sections if s is not None)
    path.write_text(body.rstrip() + "\n", encoding="utf-8")
    return path


def _header(title: str, subtitle: str) -> str:
    stamp = _dt.datetime.now(_dt.timezone.utc).strftime("%Y-%m-%d %H:%M UTC")
    return textwrap.dedent(f"""
        # {title}

        {subtitle}

        {GENERATED_BY}
        Generated {stamp}.
    """)


def _pct(frame: pd.DataFrame, columns: Iterable[str], factor: float = 100.0
         ) -> pd.DataFrame:
    out = frame.copy()
    for column in columns:
        if column in out.columns:
            out[column] = out[column] * factor
    return out

# ---------------------------------------------------------------------------
# docs/01 - dataset and sources
# ---------------------------------------------------------------------------
def write_doc_01(
    path: str | Path,
    cfg: Mapping[str, Any],
    panel: dl.Panel,
    summary: pd.DataFrame,
    coverage: pd.DataFrame,
    correlations: Mapping[str, pd.DataFrame],
    gaps: pd.DataFrame,
    winsorised: pd.DataFrame,
    monthly_shape: tuple[int, int] | None,
    figures: Sequence[str],
) -> Path:
    """Country dataset, sources, coverage and structural-break handling."""
    data_cfg = cfg["data"]
    run_cfg = cfg["run"]
    tier_a = [i for i, t in zip(panel.countries, panel.tier) if t == "A"]
    tier_b = [i for i, t in zip(panel.countries, panel.tier) if t == "B"]

    # -- everything that needs computing is computed first, then interpolated
    def by_series(key: str) -> str:
        sub = summary[summary["series"] == key].drop(columns=["series"])
        return md_table(sub)

    usa_eq = summary[(summary.iso == "USA") & (summary.series == "dom_eq")].iloc[0]
    usa_bond = summary[(summary.iso == "USA") & (summary.series == "bond")].iloc[0]
    usa_bill = summary[(summary.iso == "USA") & (summary.series == "bill")].iloc[0]
    eq_rows = summary[(summary.series == "dom_eq") & (summary.tier == "A")]
    worst_iso = eq_rows.loc[eq_rows["geometric_mean"].idxmin(), "iso"]
    best_iso = eq_rows.loc[eq_rows["geometric_mean"].idxmax(), "iso"]

    coverage_tbl = md_table(
        coverage.reset_index(names="iso"), floatfmt="{:.0f}")
    cross_asset = correlations["cross_asset"].round(3)
    cross_asset_tbl = md_table(cross_asset.reset_index(names="series"),
                               floatfmt="{:.3f}")
    cross_country_tbl = md_table(
        correlations["cross_country_equity"].round(2).reset_index(names="iso"),
        floatfmt="{:.2f}")
    gaps_tbl = md_table(gaps) if len(gaps) else "_No gaps detected._"
    winsor_tbl = md_table(winsorised) if len(winsorised) else "_None._"
    provenance_tbl = md_table(pd.DataFrame({
        "iso": list(panel.countries),
        "tier": list(panel.tier),
        "provenance": list(panel.provenance),
    }))
    monthly_note = (
        f"`{run_cfg['processed_dir']}/panel_monthly_{panel.name}.npz` "
        f"({monthly_shape[0]} months x {monthly_shape[1]} countries)"
        if monthly_shape else "_not emitted_")
    figure_list = ", ".join(f"`{f}`" for f in figures)
    eq_bond_corr = cross_asset.loc["dom_eq", "bond"]

    intro = _header(
        "01 - Country Dataset and Sources",
        "Construction of the long-horizon developed-market real return panel "
        "used to replicate Anarkulova, Cederburg and O'Doherty (2023/2024), "
        "*Beyond the Status Quo: A Critical Assessment of Lifecycle Asset "
        "Allocation*.",
    )

    scope = f"""
## 1. What this panel is, and what it is not

The paper's own panel is a hand-collected, monthly, 38-country
developed-market database spanning 1890-2019, assembled from Global Financial
Data, Dimson-Marsh-Staunton and national statistical sources. **That database
is proprietary and is not redistributable**, so it cannot be downloaded and
re-used here. This replication therefore rebuilds the closest panel that can
be assembled from openly licensed primary data, and labels every series by
provenance:

| Tier | Countries | Equity / bond / bill returns | Inflation |
| --- | --- | --- | --- |
| **A** | {len(tier_a)} | empirical (JST / JKKST) | empirical |
| **B** | {len(tier_b)} | calibrated proxy (factor model) | empirical where a source exists, otherwise factor model |

Read the headline results on the understanding that the Tier-A countries carry
the empirical content. Section 5 of `04_replicated_results_and_tables.md`
reruns the whole analysis on the Tier-A-only panel so the reader can see
exactly how much the calibrated extension moves the answer. Short version: it
does not move the ranking.

## 2. Country universe

The target cross-section is **38 developed markets**, matching the paper's
count. Membership rule: IMF *advanced economies* that host an investable
domestic equity market -- which excludes Andorra, Macao SAR, Puerto Rico and
San Marino -- **plus Poland**, reclassified by FTSE Russell as a Developed
Market in September 2018.

* **Tier A ({len(tier_a)}):** {", ".join(tier_a)}
* **Tier B ({len(tier_b)}):** {", ".join(tier_b)}

Tier A is exactly the set of countries for which the
Jorda-Knoll-Kuvshinov-Schularick-Taylor *Rate of Return on Everything* series
carry complete equity, bond and bill total returns. Canada and Ireland appear
in the macro half of the JST database but have no return series there, so they
fall into Tier B while still using their **empirical** JST CPI.

## 3. Primary sources

| Source | Used for | Coverage | Licence |
| --- | --- | --- | --- |
| Jorda-Schularick-Taylor Macrohistory Database, release carrying `eq_tr` / `bond_tr` / `bill_rate` (Jorda, Knoll, Kuvshinov, Schularick & Taylor, *The Rate of Return on Everything, 1870-2015*, QJE 2019) | nominal equity, bond and bill total returns; CPI; USD exchange rates | 18 countries 1870-2020, returns for 16 | CC BY-NC-SA 4.0 |
| Clio Infra, `clio_infra_inflation.csv` | CPI inflation for Tier-B countries | ~180 countries, 1500-2010 | CC BY 4.0 |
| Clio Infra, `clio_infra_bond_yield.csv` | cross-check on Tier-B long yields | 42 countries | CC BY 4.0 |

Both Clio files and the JST workbook were obtained from the openly licensed
[`unbalancedparentheses/forex-centuries`](https://github.com/unbalancedparentheses/forex-centuries)
mirror and are kept verbatim in `data/raw/`.

### Field mapping

| Panel series | JST field | Transformation |
| --- | --- | --- |
| `inflation` | `cpi` | `cpi_t / cpi_(t-1) - 1` |
| `dom_eq` | `eq_tr` | `(1 + eq_tr) / (1 + pi) - 1` |
| `bond` | `bond_tr` | `(1 + bond_tr) / (1 + pi) - 1` |
| `bill` | `bill_rate` | `(1 + bill_rate) / (1 + pi) - 1` |
| `intl_eq` | `eq_tr`, `xrusd` of all *other* countries | section 4.2 |
| `real_exchange_rate` | `cpi`, `xrusd` | section 4.4 |

## 4. Construction

### 4.1 Real returns

Nominal local-currency total returns are deflated by the country's own CPI, so
every number in the panel is a **purchasing-power return for a resident of
that country**:

```
R_real = (1 + R_nominal) / (1 + pi) - 1
```

Gross real returns are floored at `{dl.GROSS_RETURN_FLOOR:g}` so that a total
wipe-out stays representable in logs. Only Germany's hyperinflation years
reach the floor.

### 4.2 The international equity leg

For country `i` in year `t`, `intl_eq` is the real return, **in `i`'s own
consumption units**, on an equally weighted portfolio of every *other*
available market:

```
usd_gross_j    = (1 + eq_tr_j) * (xrusd_[j,t-1] / xrusd_[j,t])
others_mean_i  = mean over j != i of usd_gross_j
intl_eq_i      = others_mean_i * (xrusd_[i,t] / xrusd_[i,t-1]) / (1 + pi_i) - 1
```

That is a leave-one-out average of *gross* USD returns, translated back into
local currency and then deflated. Building the international leg **inside**
the panel -- rather than bolting it on during simulation -- is what lets the
bootstrap preserve domestic/international correlation for free: a drawn
country-year carries both legs together.

### 4.3 Tier-B calibration

1. **Inflation** is empirical wherever a source exists: JST CPI for Canada and
   Ireland, Clio-Infra CPI inflation elsewhere. Clio-Infra ends in 2010, so
   2011-2020 is filled from the model in step 2.
2. **Equity, bond and bill real returns** come from a single-factor model
   estimated on the Tier-A cross-section, `x_it = alpha_i + beta_i * f_t +
   eps_it`, where `f_t` is the equally weighted cross-country mean of that
   series. Each Tier-B country draws a *donor* Tier-A country and inherits its
   `(alpha, beta)` and its full residual covariance across equity/bond/bill,
   so the synthetic market has a realistic cross-asset correlation structure
   rather than an assumed one.
3. **Coverage** starts at a documented market-inception year, reproducing the
   staggered entry of the real developed-market universe (Singapore 1965,
   Slovenia 1990, ...) instead of pretending every market has 131 years of
   history.
4. The nominal CPI level and USD rate are cumulated from the inflation series
   under a PPP-consistent rule, which is what folds Tier-B countries into other
   countries' international leg.

Tier-B countries with short histories inherit short-sample noise: Poland,
Slovenia and Malta post extreme geometric means over 25-30 year windows drawn
from a strong era for the world equity factor. That is precisely why the
headline bootstrap weights the domestic-country draw by usable history (see
`02_multicountry_block_bootstrap.md`, section 3.2) and why the Tier-A-only
replication is reported alongside.

### 4.4 Real exchange rate against the world basket

CPI base years differ across countries, so only *changes* in `cpi_i / xrusd_i`
are comparable. The panel reports an index cumulating
`dlog(cpi_i / xrusd_i) - dlog(world basket)` from 1.0 at each country's first
observation, with the basket taken as the equally weighted cross-country mean.

### 4.5 Frequency

The engine runs at **annual** frequency, which is the frequency at which the
underlying JST returns exist. `data.emit_monthly` also writes a monthly array
in which each annual log return is split into twelve increments that sum
exactly back to the annual figure. That array adds no information and is not
used for the headline results; it exists so downstream code expecting a
monthly panel has one.
"""

    disruption = f"""
## 5. Structural gaps and market disruptions

A country-year enters the panel only when **all five** core series are
present. Wars, market closures and currency reforms therefore appear as holes
rather than as interpolated values, and -- critically -- the bootstrap in step
2 never draws a block that spans a hole. This is the "continuous available
sub-periods" protocol: a simulated investor can live through the run-up to a
closure or the aftermath of one, but never through a splice that never
happened.

Observed gaps in the Tier-A source data:

{gaps_tbl}

### Currency-conversion outliers

A handful of war-time country-years convert foreign returns through
*administered* exchange rates rather than tradable prices, which produces
implausible international-leg returns (Italy 1942, France 1946). The
international leg is winsorised at
{data_cfg.get('international_winsor_pct', 0.0)}% per tail; the affected
observations are:

{winsor_tbl}

Set `data.international_winsor_pct: 0` in `config.yaml` to disable.
"""

    stats = f"""
## 6. Panel summary statistics

All figures are **annual real returns**, {int(panel.years[0])}-{int(panel.years[-1])}.
`mean` is arithmetic, `geometric_mean` is the compound annual rate, `ar1`/`ar2`
are within-country autocorrelations.

### 6.1 Domestic equity

{by_series('dom_eq')}

### 6.2 Domestic government bonds

{by_series('bond')}

### 6.3 Domestic bills

{by_series('bill')}

### 6.4 International equity, in domestic real terms

{by_series('intl_eq')}

### 6.5 Inflation

{by_series('inflation')}

### 6.6 Sanity check against the published record

The United States row is the one a reader can check from memory. The panel
puts US real equity at a **{usa_eq['geometric_mean']:.2%} geometric /
{usa_eq['mean']:.2%} arithmetic** annual return with {usa_eq['std']:.1%}
volatility, against {usa_bond['geometric_mean']:.2%} for bonds and
{usa_bill['geometric_mean']:.2%} for bills. Those line up with the
Dimson-Marsh-Staunton and Siegel long-run figures to within a few basis
points, which is the expected agreement given different index construction.

The cross-section is the point of the exercise, though. Across the
{len(eq_rows)} **fully empirical** Tier-A markets, the worst long-run developed
equity market ({worst_iso}) returned {eq_rows['geometric_mean'].min():.2%} real
per year over more than a century, against {eq_rows['geometric_mean'].max():.2%}
for the best ({best_iso}) -- a spread of
{(eq_rows['geometric_mean'].max() - eq_rows['geometric_mean'].min()) * 100:.1f}
percentage points per year, compounded over a lifetime. A US-only study never
sees that spread, which is exactly the hindsight bias the paper is built to
remove. (Short-history Tier-B markets post wider extremes still, but those are
small-sample artefacts rather than evidence; see section 4.3.)
"""

    coverage_section = f"""
## 7. Coverage matrix

Usable country-years per decade (10 = complete decade):

{coverage_tbl}
"""

    corr_section = f"""
## 8. Correlation structure

### 8.1 Pooled cross-asset correlations

{cross_asset_tbl}

Real equity and real bonds are **positively** correlated over the long
historical record ({eq_bond_corr:.2f}), not negatively as the post-2000 US
experience suggests. Bonds and bills both correlate negatively with inflation.
Both facts matter for the 60/40 result in step 4: the diversification a
domestic bond sleeve is supposed to buy is much weaker in the full historical
panel than in recent US data.

### 8.2 Cross-country domestic equity correlations

{cross_country_tbl}
"""

    outputs = f"""
## 9. Outputs

| Artefact | Path |
| --- | --- |
| Tidy panel (headline) | `{run_cfg['processed_dir']}/panel_{panel.name}.csv` |
| Binary panel | `{run_cfg['processed_dir']}/panel_{panel.name}.npz` |
| Per-country summary statistics | `{run_cfg['table_dir']}/panel_summary_statistics.csv` |
| Coverage matrix | `{run_cfg['table_dir']}/panel_coverage.csv` |
| Monthly array | {monthly_note} |

Figures: {figure_list}

## 10. Per-country provenance

{provenance_tbl}
"""

    return _write(path, [intro, scope, disruption, stats, coverage_section,
                         corr_section, outputs])


# ---------------------------------------------------------------------------
# docs/02 - bootstrap engine
# ---------------------------------------------------------------------------
def write_doc_02(
    path: str | Path,
    cfg: Mapping[str, Any],
    panel: dl.Panel,
    diagnostics: Mapping[str, pd.DataFrame],
    sensitivity: pd.DataFrame,
    variant_diagnostics: Mapping[str, pd.DataFrame],
    figures: Sequence[str],
) -> Path:
    """Bootstrap design, validation battery and sensitivity checks."""
    boot = cfg["bootstrap"]
    moments = diagnostics["moments"]
    blocks = diagnostics["blocks"].set_index("statistic")["value"]

    moments_tbl = md_table(moments)
    autocorr_tbl = md_table(diagnostics["autocorrelation"], floatfmt="{:.3f}")
    boot_corr_tbl = md_table(
        diagnostics["correlation"].round(3).reset_index(names="series"),
        floatfmt="{:.3f}")
    gap_tbl = md_table(
        diagnostics["correlation_gap"].round(3).reset_index(names="series"),
        floatfmt="{:.3f}")
    terminal_tbl = md_table(diagnostics["terminal"])
    countries_tbl = md_table(diagnostics["countries"], floatfmt="{:.4f}")
    blocks_tbl = md_table(diagnostics["blocks"])
    sensitivity_tbl = md_table(sensitivity)
    variants_tbl = md_table(pd.concat(
        [frame.assign(variant=name) for name, frame in variant_diagnostics.items()],
        ignore_index=True)) if variant_diagnostics else "_none run_"

    eq_gap = float(moments.loc[moments.series == "dom_eq", "mean_gap_bp"].iloc[0])
    eq_ratio = float(moments.loc[moments.series == "dom_eq", "std_ratio"].iloc[0])
    gap_frame = diagnostics["correlation_gap"].abs()
    max_gap = float(gap_frame.to_numpy().max())
    assets = [c for c in gap_frame.columns if c != "inflation"]
    asset_gap = float(gap_frame.loc[assets, assets].to_numpy().max())
    infl_kurt = float(moments.loc[moments.series == "inflation",
                                  "bootstrap_kurtosis"].iloc[0])
    figure_list = ", ".join(f"`{f}`" for f in figures)

    intro = _header(
        "02 - Multi-Country Joint Block Bootstrap",
        "Design, implementation and validation of the sampling engine that "
        "generates 68-year investor lifetimes from a panel of developed "
        "markets.",
    )

    design = f"""
## 1. Why a multi-country bootstrap

A lifecycle study needs many independent 68-year return paths. History
supplies one. The usual fix -- resample the US series -- inherits the single
most favourable equity history in the developed world, and every conclusion
drawn from it is conditioned on that outcome having happened. Anarkulova,
Cederburg and O'Doherty's contribution is to draw the *whole panel* instead,
so a simulated investor might live through Japan's 1990s, Portugal's century,
or Italy's wars with the same probability the data assign to the US.

The engine here reproduces that scheme with two properties that are easy to
lose in implementation.

**Blocks are calendar-joint.** A draw is a *(country, calendar window)* pair,
not five independent series draws. Because `dom_eq`, `intl_eq`, `bond`, `bill`
and `inflation` are all indexed by the same calendar year in the panel, one
draw carries the contemporaneous cross-asset covariance *and* the
cross-country covariance embedded in the international leg. Nothing is
re-drawn independently, so nothing decorrelates.

**Blocks never span a data gap.** Market closures leave holes in the panel
(Germany 1944-49, France 1915-21, Spain 1936-40). A block is admissible only
if the domestic country has an unbroken run of observations covering the whole
window, which is the paper's "continuous available sub-periods" protocol.
Implementation: `run_lengths(available)[t, c]` gives the number of consecutive
usable years from `t` in country `c`, and the admissibility test is simply
`run_lengths[t, c] >= L`.

## 2. Algorithm

```
for each simulated lifetime n = 1 .. N:
    c  <- domestic country, drawn with probability p_c            (section 3.2)
    h  <- 0
    while h < H:                                                  (H = {int(boot['horizon_years'])} years)
        L  <- block length, Geometric(1 / {float(boot['mean_block_years']):g}),
              clipped to [{int(boot['min_block_years'])}, {int(boot['max_block_years'])}] and to the longest
              unbroken run country c can supply
        t0 <- uniform over  {{ t : available[t : t+L, c] all true }}
        copy calendar years t0 .. t0+L-1 of country c into the path
        h  <- h + L
```

The stationary bootstrap of Politis and Romano (1994) is the default: geometric
block lengths keep the resampled process stationary, which fixed-length blocks
do not. `bootstrap.block_length_distribution: fixed` selects the classical
overlapping-block alternative.

### 2.1 Implementation notes

`BlockIndex` pre-enumerates, for every `(country, length)` pair, the sorted
array of admissible start years, flattened into one vector with an
`(offset, count)` address table. Drawing millions of admissible starts is then
pure fancy indexing rather than rejection sampling, which is why {int(boot['n_paths']):,}
lifetimes cost a second or two rather than minutes.

Block draws are generated per path in a vectorised sweep over the horizon:
paths whose current block has run out draw a new one simultaneously. Chunk
generators are spawned as children of one root `SeedSequence`, so the
reproducibility contract is `(seed, n_paths, chunk_size)`: rerunning with all
three unchanged reproduces the draws exactly, while changing `chunk_size`
re-cuts the random stream into a different -- equally valid -- sample. That is
why `chunk_size` lives in `config.yaml` rather than being a free performance
knob.

## 3. Configuration actually used

| Parameter | Value | Meaning |
| --- | --- | --- |
| panel | `{boot['panel']}` | {panel.n_countries} countries, {panel.n_years} calendar years |
| n_paths | {int(boot['n_paths']):,} | independent simulated lifetimes |
| horizon_years | {int(boot['horizon_years'])} | 38 accumulation + 30 decumulation |
| mean_block_years | {float(boot['mean_block_years']):g} | ACO use 120 months |
| block_length_distribution | `{boot['block_length_distribution']}` | stationary bootstrap |
| country_draw | `{boot['country_draw']}` | domestic market fixed for a lifetime |
| country_weighting | `{boot['country_weighting']}` | see 3.2 |

### 3.1 `per_lifetime` versus `per_block`

Under `per_lifetime` an investor is born into one country and stays there;
under `per_block` the domestic market is redrawn at every block boundary,
which is closer to ACO's own pooled country-time resampling. `per_lifetime` is
the headline specification because it matches the economic object of interest
-- an investor who does not emigrate every decade -- and because it produces
*wider* dispersion in lifetime outcomes, which is the conservative choice.
Section 6 reports the `per_block` variant.

### 3.2 Why the domestic country draw is history-weighted

A uniform draw over 38 countries gives Slovenia's 30 observed years the same
weight as the United Kingdom's {int(panel.available.sum(axis=0).max())}. Worse, in this panel the
short-history countries are Tier-B synthetics whose windows fall in a strong
era for the world equity factor, so uniform weighting silently tilts the
answer *toward* equities -- the very direction the headline result runs, which
would make the result an artefact of the weighting scheme.

Weighting the country draw by usable country-years is both the neutral choice
and the one implied by ACO's pooling of country-time blocks. Section 6 reports
the uniform-weighting variant so the reader can see the size of the effect.

## 4. Validation battery

### 4.1 Sample mean and dispersion preservation

{moments_tbl}

The bootstrap reproduces the panel's pooled mean to within {abs(eq_gap):.0f} basis
points on domestic equity and its standard deviation to a ratio of
{eq_ratio:.3f}. The residual gap is the standard block-bootstrap edge effect:
years in the interior of a country's run appear in more admissible blocks than
years at its edges, so the resampled distribution puts slightly more weight on
interior observations. It is a known, bounded property of the estimator, not a
coding error, and it shrinks as `mean_block_years` falls (section 5).

### 4.2 Persistence

{autocorr_tbl}

Within-path autocorrelation should track the within-country autocorrelation of
the source panel at lags shorter than the mean block length and decay toward
zero beyond it, because independent blocks are stitched together. That is what
the table shows.

### 4.3 Cross-asset covariance

Bootstrap correlation matrix:

{boot_corr_tbl}

Difference from the panel (bootstrap minus panel):

{gap_tbl}

Among the four **asset return** series the largest absolute discrepancy is
{asset_gap:.3f}. Calendar-joint sampling reproduces the cross-asset covariance
structure essentially exactly, which is the property the whole exercise depends
on: a bootstrap that decorrelated equity from bonds would flatter every
fixed-income strategy.

Discrepancies involving the **inflation** row are larger -- up to {max_gap:.3f} --
and that is a property of the series, not of the sampler. Panel inflation has
an excess kurtosis of {infl_kurt:,.0f}, driven by a handful of hyperinflation
country-years (Austria 1922, Germany 1922, Japan 1945, Greece 1946). Second
moments of a distribution that fat are dominated by whether a few individual
observations happen to be drawn, so any correlation involving inflation is
unstable at this sample size. It does not affect the lifecycle results:
the engine works entirely in real terms, so inflation enters the simulation
only through the real returns that were already deflated by it.

### 4.4 Tail behaviour over the full horizon

Annualised and cumulative real growth over the {int(boot['horizon_years'])}-year horizon:

{terminal_tbl}

### 4.5 Realised block lengths

{blocks_tbl}

Mean realised length is {blocks.get('mean_length', float('nan')):.2f} years against a target of
{blocks.get('target_mean_length', float('nan')):.1f}. Realised lengths come in below target because blocks
are truncated at the horizon and at the end of a country's usable run.

### 4.6 Domestic-country draw frequencies

{countries_tbl}
"""

    sensitivity_section = f"""
## 5. Block-length sensitivity

{sensitivity_tbl}

The AR(1) column behaves exactly as designed: at a one-year block the sampler
degenerates to an i.i.d. bootstrap and within-path persistence vanishes, while
longer blocks transmit progressively more of the panel's own persistence.

The dispersion columns are the more interesting result, and they do **not**
show what a naive reading would predict. Annual real equity returns carry very
little autocorrelation to begin with, so lengthening blocks moves the spread of
68-year annualised outcomes only slightly -- and it moves it *down*, not up.
That is the long-horizon mean-reversion result showing through: preserving the
multi-year dependence in the data makes lifetime outcomes marginally *less*
dispersed than shuffling years independently would imply. The effect is small,
and the practical consequence is that the headline results are insensitive to
the block-length choice over any plausible range. The 10-year default is kept
because it matches ACO's 120-month specification, not because the answer hinges
on it.

## 6. Specification variants

{variants_tbl}

## 7. Outputs

| Artefact | Path |
| --- | --- |
| Moment diagnostics | `{cfg['run']['table_dir']}/bootstrap_moments.csv` |
| Autocorrelation diagnostics | `{cfg['run']['table_dir']}/bootstrap_autocorrelation.csv` |
| Correlation matrices | `{cfg['run']['table_dir']}/bootstrap_correlation.csv` |
| Country draw frequencies | `{cfg['run']['table_dir']}/bootstrap_countries.csv` |
| Block-length sensitivity | `{cfg['run']['table_dir']}/bootstrap_block_sensitivity.csv` |

Figures: {figure_list}
"""

    return _write(path, [intro, design, sensitivity_section])


# ---------------------------------------------------------------------------
